function Mark({ d }: { d: string }) {
  return (
    <svg viewBox="0 0 24 24" aria-hidden="true" className="h-4 w-4 shrink-0" fill="currentColor">
      <path d={d} />
    </svg>
  );
}

export default function Integrations() {
  const [active, setActive] = useState(0);
  const cat = CATEGORIES[active];

  return (
    <Reveal className="mt-16 sm:mt-20">
      <div className="rounded-3xl border border-[var(--border)] bg-[var(--surface)] p-6 sm:p-10">
        <div className="grid gap-8 lg:grid-cols-[minmax(0,1fr)_minmax(0,1.6fr)] lg:gap-12">
          {/* copy + tabs */}
          <div>
            <span className="section-eyebrow">Integrations</span>
            <h3 className="font-display mt-3 text-xl font-semibold tracking-tight sm:text-2xl">
              We connect whatever your product runs on
            </h3>
            <p className="mt-3 text-sm leading-relaxed text-[var(--text-muted)]">
              Payments, banking, CRM, logistics, AI — if it has an API, we have
              probably wired it in. These are the ones that come up most often.
            </p>

            <div className="mt-6 flex flex-wrap gap-2" role="tablist" aria-label="Integration categories">
              {CATEGORIES.map((c, i) => (
                <button
                  key={c.name}
                  role="tab"
                  aria-selected={i === active}
                  onClick={() => setActive(i)}
                  className={`cursor-pointer rounded-full border px-3.5 py-1.5 text-xs font-medium transition-colors sm:text-sm ${
                    i === active
                      ? 'border-[var(--accent-1)]/50 bg-[var(--accent-1)]/12 text-[var(--fg)]'
                      : 'border-[var(--border-soft)] bg-transparent text-[var(--text-muted)] hover:border-[var(--border)] hover:text-[var(--fg)]'
                  }`}
                >
                  {c.name}
                </button>
              ))}
            </div>
          </div>

          {/* chips */}
          <ul
            key={cat.name}
            role="tabpanel"
            className="flex flex-wrap content-start gap-2 animate-[fadeScale_0.35s_ease-out]"
          >
            {cat.items.map((it) => (
              <li
                key={it.label}
                className="inline-flex items-center gap-2 rounded-full border border-[var(--border-soft)] bg-[var(--surface)] px-3.5 py-2 text-xs text-[var(--text-muted)] transition-colors hover:border-[var(--border)] hover:text-[var(--fg)] sm:text-sm"
              >
                {it.d ? <Mark d={it.d} /> : <Plug className="h-4 w-4 shrink-0 opacity-70" />}
                {it.label}
              </li>
            ))}
          </ul>
        </div>
      </div>
    </Reveal>
  );
}
